<script setup>import { useToastStore } from '../stores/toast'; const toast = useToastStore()</script>
<template><div class="toast-viewport" role="status" aria-live="polite" aria-atomic="false" aria-relevant="additions"><TransitionGroup name="toast"><div v-for="item in toast.messages" :key="item.id" class="toast-item" :class="`toast-${item.type}`"><span>{{ item.message }}</span><button type="button" :aria-label="$t('common.close')" :title="$t('common.close')" @click="toast.dismiss(item.id)">×</button></div></TransitionGroup></div></template>
